begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text); grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('65000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n))::text,true)$$;
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(3))$$;
create function pg_temp.start(n integer) returns jsonb language sql as $$select public.agri_command('start_blind_count',pg_temp.ctx()||jsonb_build_object('countId',pg_temp.i(n),'productId',pg_temp.i(5),'batchId',null,'reason','TEST blind feeds count'))$$;
create function pg_temp.seal(n integer,s text,q text,obs integer) returns jsonb language sql as $$select public.agri_command('record_blind_count',pg_temp.ctx()||jsonb_build_object('countId',pg_temp.i(n),'stage',s,'quantity',q,'notes','TEST independent physical evidence','observationId',pg_temp.i(obs)))$$;
create function pg_temp.approve(n integer) returns jsonb language sql as $$select public.agri_command('approve_count',pg_temp.ctx()||jsonb_build_object('countId',pg_temp.i(n),'reason','TEST two sealed counts checked'))$$;
set local role authenticated;
select pg_temp.login(15);
select pg_temp.login(17);
select pg_temp.login(16);
select pg_temp.login(12);
select pg_temp.login(11);
select pg_temp.login(13);
select pg_temp.login(11);
select pg_temp.login(12);
select pg_temp.login(11);
select pg_temp.login(14);
select pg_temp.login(12);
select pg_temp.login(11);
select pg_temp.login(12);
select pg_temp.login(11);
reset role;
set local role authenticated;
select pg_temp.login(14);
select pg_temp.login(12);
reset role;
set local role authenticated;
select pg_temp.login(13);
select pg_temp.login(12);
select pg_temp.login(13);
reset role;
update public.staff_memberships set active=false where user_id=pg_temp.i(12);
set local role authenticated;
select pg_temp.login(11);
select pg_temp.login(12);
reset role;
set local role authenticated;
select pg_temp.login(14);
select pg_temp.login(13);
select pg_temp.login(11);
reset role;
 values(pg_temp.i(108),pg_temp.i(1),pg_temp.i(3),pg_temp.i(5),500,499,0,'TEST retained legacy pending count',pg_temp.i(11));
set local role authenticated;
select pg_temp.login(11);
reset role;
 select pg_temp.i(n),pg_temp.i(1),pg_temp.i(3),pg_temp.i(5),500,0,pg_temp.i(11),'TEST pagination history','cancelled','2027-01-01T00:00:00.123456Z'::timestamptz from generate_series(200,260)n;
set local role authenticated;
select pg_temp.login(11);
create temporary table count_page as select public.agri_command('count_workspace',pg_temp.ctx()) result;
create temporary table next_count_page as select public.agri_command('count_workspace',pg_temp.ctx()||jsonb_build_object('beforeAt',result->'rows'->49->>'createdAt','beforeId',result->'rows'->49->>'id')) result from count_page;
reset role;
select line from tap_results;
select * from finish();
rollback;
