insert into tap_results select is((select (result->'rows'->49->>'createdAt')::timestamptz from count_page),'2027-01-01T00:00:00.123456Z'::timestamptz,'Cursor retains the exact instant and microseconds across connection timezones');
insert into tap_results select is((select jsonb_array_length(result->'rows') from next_count_page),19,'Older page retains every remaining count at a shared timestamp');
